import { useState } from "react";
import { useParams, Link } from "react-router-dom";
import { Button } from "@/components/ui/button";
import { ArrowLeft } from "lucide-react";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { ProjectDetail } from "@/components/projects/ProjectDetail";
import { BOQUpload } from "@/components/boqs/BOQUpload";
import { BOQVersionList } from "@/components/boqs/BOQVersionList";
import { BOQItemTable } from "@/components/boqs/BOQItemTable";
import { QuoteList } from "@/components/quotes/QuoteList";
import { QuoteBuilder } from "@/components/quotes/QuoteBuilder";
import { QuoteDetail } from "@/components/quotes/QuoteDetail";
import { TaskKanban } from "@/components/tasks/TaskKanban";
import { DocumentList } from "@/components/documents/DocumentList";
import { ComplianceList } from "@/components/compliance/ComplianceList";

export function ProjectDetailPage() {
  const { id } = useParams<{ id: string }>();
  const [activeTab, setActiveTab] = useState("overview");
  const [viewingBoqId, setViewingBoqId] = useState<string | null>(null);
  const [viewingQuoteId, setViewingQuoteId] = useState<string | null>(null);
  const [showQuoteBuilder, setShowQuoteBuilder] = useState(false);
  const [showQuoteDetail, setShowQuoteDetail] = useState(false);

  if (!id) return null;

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Button variant="ghost" asChild>
          <Link to="/projects">
            <ArrowLeft className="mr-2 h-4 w-4" />
            Back to Projects
          </Link>
        </Button>
      </div>

      <Tabs value={activeTab} onValueChange={setActiveTab}>
        <TabsList>
          <TabsTrigger value="overview">Overview</TabsTrigger>
          <TabsTrigger value="boqs">BOQs</TabsTrigger>
          <TabsTrigger value="quotes">Quotes</TabsTrigger>
          <TabsTrigger value="tasks">Tasks</TabsTrigger>
          <TabsTrigger value="documents">Documents</TabsTrigger>
          <TabsTrigger value="compliance">Compliance</TabsTrigger>
        </TabsList>

        <TabsContent value="overview">
          <ProjectDetail projectId={id} />
        </TabsContent>

        <TabsContent value="boqs">
          <div className="space-y-4">
            <BOQUpload projectId={id} />
            <BOQVersionList projectId={id} onViewVersion={(boqId) => setViewingBoqId(boqId)} />
            {viewingBoqId && (
              <div className="mt-4 space-y-2">
                <BOQItemTable projectId={id} boqId={viewingBoqId} />
                <Button variant="outline" onClick={() => setViewingBoqId(null)}>Close</Button>
              </div>
            )}
          </div>
        </TabsContent>

        <TabsContent value="quotes">
          <div className="space-y-4">
            <QuoteList
              projectId={id}
              onViewQuote={(quoteId) => { setViewingQuoteId(quoteId); setShowQuoteDetail(true); }}
              onNewQuote={() => setShowQuoteBuilder(true)}
            />
          </div>
        </TabsContent>

        <TabsContent value="tasks">
          <TaskKanban projectId={id} />
        </TabsContent>

        <TabsContent value="documents">
          <DocumentList projectId={id} />
        </TabsContent>

        <TabsContent value="compliance">
          <ComplianceList projectId={id} />
        </TabsContent>
      </Tabs>

      <QuoteBuilder
        projectId={id}
        open={showQuoteBuilder}
        onOpenChange={setShowQuoteBuilder}
        onCreated={(quoteId) => {
          setShowQuoteBuilder(false);
          setViewingQuoteId(quoteId);
          setShowQuoteDetail(true);
        }}
      />

      {viewingQuoteId && (
        <QuoteDetail
          quoteId={viewingQuoteId}
          projectId={id}
          open={showQuoteDetail}
          onOpenChange={setShowQuoteDetail}
        />
      )}
    </div>
  );
}

